-- ================================================================
-- GreenApps — Módulo Contratos, Centros de Costos y Áreas Verdes Zona 6
-- ================================================================

-- 1. TABLA: contratos
CREATE TABLE IF NOT EXISTS public.contratos (
  id                  TEXT PRIMARY KEY,
  codigo              TEXT NOT NULL UNIQUE,
  nombre              TEXT NOT NULL,
  empresa             TEXT NOT NULL DEFAULT 'AKRO',
  mandante            TEXT NOT NULL DEFAULT 'Ilustre Municipalidad de Maipú',
  comuna              TEXT NOT NULL DEFAULT 'Maipú',
  centro_costo_codigo TEXT,
  documento_bases     TEXT DEFAULT 'BASES_TÉCNICAS_ZONA_6.pdf',
  activo              BOOLEAN DEFAULT TRUE,
  created_at          TIMESTAMPTZ DEFAULT NOW()
);

-- 2. TABLA: centros_costos
CREATE TABLE IF NOT EXISTS public.centros_costos (
  codigo              TEXT PRIMARY KEY,
  nombre              TEXT NOT NULL,
  contrato_id         TEXT REFERENCES public.contratos(id) ON DELETE SET NULL,
  presupuesto_mensual NUMERIC(14,2) DEFAULT 0.00,
  moneda              TEXT DEFAULT 'CLP',
  activo              BOOLEAN DEFAULT TRUE,
  created_at          TIMESTAMPTZ DEFAULT NOW()
);

-- 3. INSERCIÓN DE CONTRATOS Y CENTROS DE COSTOS INICIALES
ON CONFLICT (id) DO UPDATE SET
  codigo = EXCLUDED.codigo,
  nombre = EXCLUDED.nombre,
  documento_bases = EXCLUDED.documento_bases;
ON CONFLICT (codigo) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  contrato_id = EXCLUDED.contrato_id;

-- 4. ESTRUCTURA COMPLETA: areas_verdes
CREATE TABLE IF NOT EXISTS public.areas_verdes (
  codigo              TEXT PRIMARY KEY,
  caracteristica      TEXT,
  nombre              TEXT NOT NULL,
  ubicacion           TEXT,
  superficie_m2       NUMERIC(12,2) DEFAULT 0,
  barrio              TEXT,
  juegos_infantiles   INT DEFAULT 0,
  juegos_inclusivos   INT DEFAULT 0,
  pilones_agua        TEXT,
  contrato_id         TEXT REFERENCES public.contratos(id) DEFAULT 'maipu_6',
  activo              BOOLEAN DEFAULT TRUE,
  created_at          TIMESTAMPTZ DEFAULT NOW()
);

-- Asegurar columnas si la tabla ya existía
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS caracteristica TEXT;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS ubicacion TEXT;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS superficie_m2 NUMERIC(12,2) DEFAULT 0;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS barrio TEXT;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS juegos_infantiles INT DEFAULT 0;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS juegos_inclusivos INT DEFAULT 0;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS pilones_agua TEXT;
ALTER TABLE public.areas_verdes ADD COLUMN IF NOT EXISTS contrato_id TEXT REFERENCES public.contratos(id) DEFAULT 'maipu_6';


-- 5. POBLAR 436 ÁREAS VERDES OFICIALES DE MAIPÚ ZONA 6 (AKRO)
ON CONFLICT (codigo) DO UPDATE SET
  caracteristica = EXCLUDED.caracteristica,
  nombre = EXCLUDED.nombre,
  ubicacion = EXCLUDED.ubicacion,
  superficie_m2 = EXCLUDED.superficie_m2,
  barrio = EXCLUDED.barrio,
  juegos_infantiles = EXCLUDED.juegos_infantiles,
  juegos_inclusivos = EXCLUDED.juegos_inclusivos,
  pilones_agua = EXCLUDED.pilones_agua,
  contrato_id = EXCLUDED.contrato_id;

-- 6. POLÍTICAS DE SEGURIDAD (RLS)
ALTER TABLE public.contratos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.centros_costos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.areas_verdes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Lectura publica de contratos" ON public.contratos;
CREATE POLICY "Lectura publica de contratos" ON public.contratos FOR SELECT USING (true);

DROP POLICY IF EXISTS "Lectura publica de centros_costos" ON public.centros_costos;
CREATE POLICY "Lectura publica de centros_costos" ON public.centros_costos FOR SELECT USING (true);

DROP POLICY IF EXISTS "Lectura publica de areas_verdes" ON public.areas_verdes;
CREATE POLICY "Lectura publica de areas_verdes" ON public.areas_verdes FOR SELECT USING (true);
